INSERT INTO feature VALUES('sized-integers','types','Sized integer arithmetic','native-primitives','partial','ordinary',NULL,'Each integer width has the operations of Rust''s integer of the same name, called by the qualified name, `u8.wrapping_add`: `wrapping_`, `saturating_` and `checked_` addition, subtraction and multiplication, `wrapping_div` and `wrapping_rem`, which stop the run on a zero divisor, the bitwise `and`, `or`, `xor` and `not`, `checked_shl` and `checked_shr`, and the six comparisons. A `checked_` form answers `w + Unit`, with the absence on the right. A value of a width is a machine integer of two words, a header with the tag of its width and its bits, and it takes no row of the literal table. The `wrapping_` addition, subtraction and multiplication and the bitwise `and`, `or`, `xor` and `not` run as a block of machine code on each target, and each answer allocates its one machine integer. The `saturating_` and `checked_` forms, `wrapping_div`, `wrapping_rem`, `checked_shl`, `checked_shr`, the comparisons and the conversions stay calls to the host. The raw word in place of the machine integer is not yet in, and nor is the method form `x.wrapping_add(y)`.','core-term core-checker runtime-emitter runtime-stencils surface-lowering','corpus/model/basics/machine-widths.gandr','corpus/ledger/features/sized-integers.gandr','#318 #8003 #8145 #8156');
